use slint::{Color, ComponentHandle, Model, ModelRc, SharedString, VecModel};
use std::cell::RefCell;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use std::time::Instant;

#[cfg(windows)]
use std::os::windows::process::CommandExt;
#[cfg(windows)]
const CREATE_NO_WINDOW: u32 = 0x08000000;

use crate::autocomplete::{AutocompleteEngine, Suggestion};
use crate::compiler::CompilerRunner;
use crate::fs_manager::FileManager;
use crate::session::{self, AppSession};
use crate::syntax::intel8080::highlight_document;

// Generated by slint_build::compile
slint::include_modules!();

pub struct IdeController {
    pub file_manager: FileManager,
    pub autocomplete: AutocompleteEngine,
    pub active_suggestions: Vec<Suggestion>,
    pub logs: Vec<String>,
    pub undo_manager: crate::editor::undo::UndoManager,
}

impl IdeController {
    pub fn new<P: AsRef<Path>>(root_dir: P) -> Self {
        Self {
            file_manager: FileManager::new(root_dir),
            autocomplete: AutocompleteEngine::new(),
            active_suggestions: Vec::new(),
            logs: vec![
                "[SYSTEM] ASMCode Intel 8080 IDE ready.".to_string(),
                "[TOOLCHAIN] Compiler: C:\\bin\\asmx20.exe".to_string(),
                "[TOOLCHAIN] Emulator: C:\\bin\\cpmemu.exe".to_string(),
            ],
            undo_manager: crate::editor::undo::UndoManager::new(String::new(), 0),
        }
    }

    pub fn append_log(&mut self, message: &str) {
        self.logs.push(message.to_string());
    }

    pub fn get_combined_logs(&self) -> String {
        self.logs.join("\n")
    }
}

fn sync_logs(ui: &AppWindow, ctrl: &IdeController) {
    ui.set_output_log_text(SharedString::from(ctrl.get_combined_logs()));
    update_terminal_lines(ui, &ctrl.logs);
}

fn persist_current_session(app: &AppWindow, ctrl: &IdeController) {
    let session = AppSession {
        last_open_folder: Some(ctrl.file_manager.current_dir.to_string_lossy().to_string()),
        last_open_file: ctrl
            .file_manager
            .active_file_path
            .as_ref()
            .map(|p| p.to_string_lossy().to_string()),
        editor_font_size: app.get_editor_font_size(),
        editor_font_italic: app.get_editor_font_italic(),
        current_language: app.get_current_language().to_string(),
        labels_expanded: app.get_labels_expanded(),
        terminal_expanded: app.get_terminal_expanded(),
        sidebar_width: app.get_sidebar_width(),
        terminal_height: app.get_terminal_height(),
    };
    session::save_session(&session);
}
pub fn setup_ui(app: &AppWindow, controller_rc: Arc<Mutex<IdeController>>, session: AppSession) {
    // 0. Restore session settings
    app.set_editor_font_size(session.editor_font_size);
    app.set_editor_font_italic(session.editor_font_italic);
    app.set_current_language(SharedString::from(&session.current_language));
    app.set_labels_expanded(session.labels_expanded);
    app.set_terminal_expanded(session.terminal_expanded);
    app.set_sidebar_width(session.sidebar_width);
    app.set_terminal_height(session.terminal_height);

    // Initial terminal lines
    {
        let ctrl = controller_rc.lock().unwrap();
        update_terminal_lines(app, &ctrl.logs);
    }
    app.set_editor_font_italic(session.editor_font_italic);
    app.set_current_language(SharedString::from(&session.current_language));
    app.set_labels_expanded(session.labels_expanded);
    app.set_terminal_expanded(session.terminal_expanded);
    // 1. Populate Docs List
    populate_docs_ui(app, &session.current_language);

    // 2. Load File List
    refresh_files_ui(app, &controller_rc);

    // 3. Initial load of last opened file or 8080.asm/main.asm
    {
        let target_opt = if let Some(ref last_file) = session.last_open_file {
            let p = PathBuf::from(last_file);
            if p.exists() {
                Some(p)
            } else {
                None
            }
        } else {
            None
        }
        .or_else(|| {
            let ctrl = controller_rc.lock().unwrap();
            if ctrl.file_manager.current_dir.join("8080.asm").exists() {
                Some(ctrl.file_manager.current_dir.join("8080.asm"))
            } else if ctrl.file_manager.current_dir.join("main.asm").exists() {
                Some(ctrl.file_manager.current_dir.join("main.asm"))
            } else {
                None
            }
        });

        if let Some(target_file) = target_opt {
            let mut ctrl = controller_rc.lock().unwrap();
            if let Ok(content) = ctrl.file_manager.read_file_content(&target_file) {
                let fname = target_file
                    .file_name()
                    .unwrap_or_default()
                    .to_string_lossy()
                    .to_string();
                let is_asm =
                    fname.ends_with(".asm") || fname.ends_with(".inc") || fname.ends_with(".s");
                app.set_active_file_name(SharedString::from(&fname));
                app.set_active_file_path(SharedString::from(
                    target_file.to_string_lossy().to_string(),
                ));
                app.set_code_text(SharedString::from(&content));
                app.set_is_dirty(false);
                app.set_is_active_asm(is_asm);
                update_highlight_and_labels(app, &ctrl.autocomplete, &content, is_asm);
            }
        }
    }

    // 4. Initial suggestions (Russian)
    refresh_suggestions_ui(app, &controller_rc, "", "ru");

    // 5. Connect UI Callbacks:

    // Close Active File
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_close_active_file(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.file_manager.active_file_path = None;
        ui.set_active_file_name(SharedString::default());
        ui.set_active_file_path(SharedString::default());
        ui.set_code_text(SharedString::default());
        ui.set_highlight_lines(ModelRc::default());
        ui.set_label_list(ModelRc::default());
        ui.set_line_numbers_text(SharedString::default());
        ui.set_is_dirty(false);
    });

    // Folder Double-Click State Tracker: (last_path, last_click_instant)
    let last_folder_click: Rc<RefCell<Option<(PathBuf, Instant)>>> = Rc::new(RefCell::new(None));

    // File Clicked in Sidebar (Single-click opens file; Click/Double-click toggles tree folder expansion)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    let folder_click_clone = Rc::clone(&last_folder_click);
    app.on_file_clicked(move |path_str, is_dir| {
        let Some(ui) = app_weak.upgrade() else { return };
        let path = PathBuf::from(path_str.as_str());

        if is_dir {
            let mut ctrl = ctrl_clone.lock().unwrap();
            ctrl.file_manager.toggle_folder(&path);
            drop(ctrl);
            refresh_files_ui(&ui, &ctrl_clone);
        } else {
            *folder_click_clone.borrow_mut() = None;
            let mut ctrl = ctrl_clone.lock().unwrap();
            match ctrl.file_manager.read_file_content(&path) {
                Ok(content) => {
                    let file_name = path
                        .file_name()
                        .map(|s| s.to_string_lossy().to_string())
                        .unwrap_or_else(|| "file.asm".to_string());
                    ui.set_active_file_name(SharedString::from(&file_name));
                    ui.set_active_file_path(SharedString::from(path.to_string_lossy().to_string()));
                    ui.set_code_text(SharedString::from(&content));
                    ui.set_is_dirty(false);
                    ctrl.undo_manager.reset(content.clone(), 0);

                    ctrl.append_log(&format!("[FILE] Opened '{}'", path.display()));
                    sync_logs(&ui, &ctrl);

                    let ext = path
                        .extension()
                        .and_then(|e| e.to_str())
                        .unwrap_or("")
                        .to_ascii_lowercase();
                    let is_asm = matches!(ext.as_str(), "asm" | "inc" | "s" | "mac");
                    ui.set_is_active_asm(is_asm);

                    let auto = ctrl.autocomplete.clone();
                    persist_current_session(&ui, &ctrl);
                    drop(ctrl);
                    update_highlight_and_labels(&ui, &auto, &content, is_asm);
                }
                Err(err) => {
                    ctrl.append_log(&format!("[ERROR] Could not read file: {}", err));
                    sync_logs(&ui, &ctrl);
                }
            }
        }
    });

    // Navigate Parent
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_navigate_parent(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        if ctrl.file_manager.navigate_parent() {
            persist_current_session(&ui, &ctrl);
            drop(ctrl);
            refresh_files_ui(&ui, &ctrl_clone);
        }
    });

    // Refresh Files
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_refresh_files(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        refresh_files_ui(&ui, &ctrl_clone);
    });

    // Create New File
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_create_file(move |name| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        match ctrl.file_manager.create_new_file(name.as_str()) {
            Ok((new_path, initial_content)) => {
                let file_name = new_path
                    .file_name()
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or_else(|| "new.asm".to_string());

                ui.set_active_file_name(SharedString::from(&file_name));
                ui.set_active_file_path(SharedString::from(new_path.to_string_lossy().to_string()));
                ui.set_code_text(SharedString::from(&initial_content));
                ui.set_is_dirty(false);
                ui.set_is_active_asm(true);

                ctrl.append_log(&format!("[FILE] Created '{}'", new_path.display()));
                sync_logs(&ui, &ctrl);

                let auto = ctrl.autocomplete.clone();
                drop(ctrl);
                refresh_files_ui(&ui, &ctrl_clone);
                update_highlight_and_labels(&ui, &auto, &initial_content, true);
            }
            Err(err) => {
                ctrl.append_log(&format!("[ERROR] Could not create file: {}", err));
                sync_logs(&ui, &ctrl);
            }
        }
    });

    // Create New Folder
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_create_new_folder(move |name| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        match ctrl.file_manager.create_new_folder(name.as_str()) {
            Ok(new_folder) => {
                ctrl.append_log(&format!(
                    "[EXPLORER] Created directory '{}'",
                    new_folder.display()
                ));
                sync_logs(&ui, &ctrl);
                persist_current_session(&ui, &ctrl);
                drop(ctrl);
                refresh_files_ui(&ui, &ctrl_clone);
            }
            Err(err) => {
                ctrl.append_log(&format!("[ERROR] Could not create folder: {}", err));
                sync_logs(&ui, &ctrl);
            }
        }
    });

    // Rename File or Folder
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_rename_file(move |old_path_str, new_name| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        let old_path = PathBuf::from(old_path_str.as_str());
        match ctrl.file_manager.rename_path(&old_path, new_name.as_str()) {
            Ok(new_path) => {
                ctrl.append_log(&format!("[EXPLORER] Renamed to '{}'", new_path.display()));
                sync_logs(&ui, &ctrl);
                if let Some(ref active) = ctrl.file_manager.active_file_path {
                    let fname = active
                        .file_name()
                        .unwrap_or_default()
                        .to_string_lossy()
                        .to_string();
                    ui.set_active_file_name(SharedString::from(&fname));
                    ui.set_active_file_path(SharedString::from(
                        active.to_string_lossy().to_string(),
                    ));
                }
                persist_current_session(&ui, &ctrl);
                drop(ctrl);
                refresh_files_ui(&ui, &ctrl_clone);
            }
            Err(err) => {
                ctrl.append_log(&format!("[ERROR] Could not rename: {}", err));
                sync_logs(&ui, &ctrl);
            }
        }
    });

    // Delete File or Folder
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_delete_file_requested(move |path_str| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        let path = PathBuf::from(path_str.as_str());
        match ctrl.file_manager.delete_path(&path) {
            Ok(()) => {
                ctrl.append_log(&format!("[EXPLORER] Deleted '{}'", path.display()));
                sync_logs(&ui, &ctrl);
                if ctrl.file_manager.active_file_path.is_none() {
                    ui.set_code_text(SharedString::default());
                    ui.set_active_file_name(SharedString::default());
                    ui.set_active_file_path(SharedString::default());
                    ui.set_highlight_lines(ModelRc::default());
                    ui.set_label_list(ModelRc::default());
                    ui.set_line_numbers_text(SharedString::default());
                }
                persist_current_session(&ui, &ctrl);
                drop(ctrl);
                refresh_files_ui(&ui, &ctrl_clone);
            }
            Err(err) => {
                ctrl.append_log(&format!("[ERROR] Could not delete: {}", err));
                sync_logs(&ui, &ctrl);
            }
        }
    });

    // Copy Path to Clipboard
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_copy_path_requested(move |path_str| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        let mut cmd = Command::new("powershell");
        #[cfg(windows)]
        cmd.creation_flags(CREATE_NO_WINDOW);
        let _ = cmd
            .arg("-NoProfile")
            .arg("-Command")
            .arg(format!(
                "Set-Clipboard -Value '{}'",
                path_str.replace("'", "''")
            ))
            .spawn();
        ctrl.append_log(&format!(
            "[EXPLORER] Copied path to clipboard: {}",
            path_str
        ));
        sync_logs(&ui, &ctrl);
    });

    // Reveal in Windows File Explorer
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_reveal_in_explorer_requested(move |path_str| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        let _ = Command::new("explorer")
            .arg(format!("/select,{}", path_str))
            .spawn();
        ctrl.append_log(&format!(
            "[EXPLORER] Revealed in File Explorer: {}",
            path_str
        ));
        sync_logs(&ui, &ctrl);
    });

    // Save File
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_save_file(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let active_name = ui.get_active_file_name().to_string();
        if active_name.is_empty() {
            return;
        }

        let mut ctrl = ctrl_clone.lock().unwrap();
        let text = ui.get_code_text().to_string();

        let save_path = if let Some(path) = &ctrl.file_manager.active_file_path {
            path.clone()
        } else {
            ctrl.file_manager
                .current_dir
                .join(&active_name)
        };

        match ctrl.file_manager.write_file_content(&save_path, &text) {
            Ok(()) => {
                ui.set_is_dirty(false);
                ctrl.append_log(&format!(
                    "[FILE] Saved '{}' ({} bytes)",
                    save_path.display(),
                    text.len()
                ));
                ui.set_status_message(SharedString::from("Saved"));
                ui.set_status_color(Color::from_rgb_u8(166, 227, 161));
                sync_logs(&ui, &ctrl);
            }
            Err(err) => {
                ctrl.append_log(&format!("[ERROR] Save failed: {}", err));
                ui.set_status_message(SharedString::from("Save failed"));
                ui.set_status_color(Color::from_rgb_u8(243, 139, 168));
                sync_logs(&ui, &ctrl);
            }
        }
    });

    // Open File Dialog (Windows Native Modern File Picker - Asynchronous via rfd, No Console Window)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_open_file_dialog(move || {
        let app_weak_inner = app_weak.clone();
        let ctrl_clone_inner = Arc::clone(&ctrl_clone);
        std::thread::spawn(move || {
            let start_dir = {
                let ctrl = ctrl_clone_inner.lock().unwrap();
                ctrl.file_manager.current_dir.clone()
            };
            if let Some(path) = rfd::FileDialog::new()
                .set_title("Open Intel 8080 File")
                .set_directory(&start_dir)
                .add_filter("Assembly Files (*.asm, *.inc, *.mac)", &["asm", "inc", "mac", "s"])
                .add_filter("All Files (*.*)", &["*"])
                .pick_file()
            {
                let _ = slint::invoke_from_event_loop(move || {
                    let Some(ui) = app_weak_inner.upgrade() else { return };
                    let mut ctrl = ctrl_clone_inner.lock().unwrap();
                    if let Ok(content) = ctrl.file_manager.read_file_content(&path) {
                        let file_name = path
                            .file_name()
                            .map(|s| s.to_string_lossy().to_string())
                            .unwrap_or_else(|| "file.asm".to_string());
                        ui.set_active_file_name(SharedString::from(&file_name));
                        ui.set_active_file_path(SharedString::from(path.to_string_lossy().to_string()));
                        ui.set_code_text(SharedString::from(&content));
                        ui.set_is_dirty(false);
                        ctrl.undo_manager.reset(content.clone(), 0);

                        ctrl.append_log(&format!("[FILE] Opened from disk: '{}'", path.display()));
                        sync_logs(&ui, &ctrl);

                        let ext = path
                            .extension()
                            .and_then(|e| e.to_str())
                            .unwrap_or("")
                            .to_ascii_lowercase();
                        let is_asm = matches!(ext.as_str(), "asm" | "inc" | "s" | "mac");
                        ui.set_is_active_asm(is_asm);

                        let auto = ctrl.autocomplete.clone();
                        persist_current_session(&ui, &ctrl);
                        drop(ctrl);
                        update_highlight_and_labels(&ui, &auto, &content, is_asm);
                    }
                });
            }
        });
    });

    // Open Folder Dialog (Windows Native Modern Folder Picker - Asynchronous via rfd, No Console Window)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_open_folder_dialog(move || {
        let app_weak_inner = app_weak.clone();
        let ctrl_clone_inner = Arc::clone(&ctrl_clone);
        std::thread::spawn(move || {
            let start_dir = {
                let ctrl = ctrl_clone_inner.lock().unwrap();
                ctrl.file_manager.current_dir.clone()
            };
            if let Some(folder_path) = rfd::FileDialog::new()
                .set_title("Open Workspace Folder")
                .set_directory(&start_dir)
                .pick_folder()
            {
                let folder_str = folder_path.to_string_lossy().to_string();
                let _ = slint::invoke_from_event_loop(move || {
                    let Some(ui) = app_weak_inner.upgrade() else { return };
                    let mut ctrl = ctrl_clone_inner.lock().unwrap();
                    ctrl.file_manager.current_dir = folder_path;
                    ctrl.append_log(&format!("[WORKSPACE] Switched directory to: '{}'", folder_str));
                    sync_logs(&ui, &ctrl);
                    persist_current_session(&ui, &ctrl);
                    drop(ctrl);
                    refresh_files_ui(&ui, &ctrl_clone_inner);
                });
            }
        });
    });

    // Insert Tab (Inserts 4 spaces without losing focus)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_insert_tab(move |byte_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let offset = (byte_offset as usize).min(code.len());

        let tab_spaces = "    ";
        let mut new_code = String::with_capacity(code.len() + tab_spaces.len());
        new_code.push_str(&code[..offset]);
        new_code.push_str(tab_spaces);
        new_code.push_str(&code[offset..]);

        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);

        let ctrl = ctrl_clone.lock().unwrap();
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        (offset + tab_spaces.len()) as i32
    });

    // Insert Newline (Preserving leading indentation / Auto-indent)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_insert_newline(move |byte_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let offset = (byte_offset as usize).min(code.len());

        let pre = &code[..offset];
        let line_start = pre.rfind('\n').map(|p| p + 1).unwrap_or(0);
        let current_line_so_far = &pre[line_start..];

        let leading_ws: String = current_line_so_far
            .chars()
            .take_while(|c| *c == ' ' || *c == '\t')
            .collect();

        let insert_chunk = format!("\n{}", leading_ws);
        let mut new_code = String::with_capacity(code.len() + insert_chunk.len());
        new_code.push_str(&code[..offset]);
        new_code.push_str(&insert_chunk);
        new_code.push_str(&code[offset..]);

        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);

        let ctrl = ctrl_clone.lock().unwrap();
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        (offset + insert_chunk.len()) as i32
    });

    // Apply Completion at Cursor Offset (replaces the typed prefix seamlessly)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_apply_completion_at(move |snippet, byte_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let bytes = code.as_bytes();
        let offset = (byte_offset as usize).min(bytes.len());

        let mut word_start = offset;
        while word_start > 0 {
            let b = bytes[word_start - 1];
            if b.is_ascii_alphanumeric() || b == b'_' || b == b'.' || b == b'?' || b == b'@' {
                word_start -= 1;
            } else {
                break;
            }
        }

        let mut word_end = offset;
        while word_end < bytes.len() {
            let b = bytes[word_end];
            if b.is_ascii_alphanumeric() || b == b'_' || b == b'.' || b == b'?' || b == b'@' {
                word_end += 1;
            } else {
                break;
            }
        }

        let mut new_code = String::with_capacity(code.len() + snippet.len());
        new_code.push_str(&code[..word_start]);
        new_code.push_str(snippet.as_str());
        let new_cursor_pos = new_code.len();
        new_code.push_str(&code[word_end..]);

        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);
        ui.set_show_autocomplete_popup(false);

        let ctrl = ctrl_clone.lock().unwrap();
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        new_cursor_pos as i32
    });

    // Delete Word Left (Ctrl + Backspace)
    // Strictly bounded to the start of the current line; never deletes characters on previous lines
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_delete_word_left(move |byte_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let bytes = code.as_bytes();
        let offset = (byte_offset as usize).min(bytes.len());

        let pre_bytes = &bytes[..offset];
        let line_start = pre_bytes
            .iter()
            .rposition(|&b| b == b'\n')
            .map(|p| p + 1)
            .unwrap_or(0);

        if offset <= line_start {
            return offset as i32;
        }

        let line_bytes = &bytes[line_start..offset];

        // Skip trailing whitespace on current line before cursor
        let mut end = line_bytes.len();
        while end > 0
            && (line_bytes[end - 1] == b' '
                || line_bytes[end - 1] == b'\t'
                || line_bytes[end - 1] == b'\r')
        {
            end -= 1;
        }

        let delete_rel = if end == 0 {
            0
        } else {
            let mut word_start = end;
            let is_ident = |b: u8| b.is_ascii_alphanumeric() || b == b'_';
            let first_is_ident = is_ident(line_bytes[end - 1]);
            while word_start > 0 {
                let b = line_bytes[word_start - 1];
                if b == b' ' || b == b'\t' || b == b'\r' {
                    break;
                }
                if is_ident(b) != first_is_ident {
                    break;
                }
                word_start -= 1;
            }
            word_start
        };

        let final_from = line_start + delete_rel;
        let mut new_code = String::with_capacity(code.len());
        new_code.push_str(&code[..final_from]);
        new_code.push_str(&code[offset..]);

        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);

        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.undo_manager
            .record_edit(&new_code, final_from as i32, false);
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        final_from as i32
    });

    // Undo (Ctrl + Z)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_editor_undo(move |_cursor| {
        let Some(ui) = app_weak.upgrade() else { return 0 };
        let mut ctrl = ctrl_clone.lock().unwrap();
        if let Some(snap) = ctrl.undo_manager.undo() {
            ui.set_code_text(SharedString::from(&snap.text));
            ui.set_is_dirty(true);
            let is_asm = ui.get_is_active_asm();
            update_highlight_and_labels(&ui, &ctrl.autocomplete, &snap.text, is_asm);
            snap.cursor_offset
        } else {
            0
        }
    });

    // Redo (Ctrl + Y or Ctrl + Shift + Z)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_editor_redo(move |_cursor| {
        let Some(ui) = app_weak.upgrade() else { return 0 };
        let mut ctrl = ctrl_clone.lock().unwrap();
        if let Some(snap) = ctrl.undo_manager.redo() {
            ui.set_code_text(SharedString::from(&snap.text));
            ui.set_is_dirty(true);
            let is_asm = ui.get_is_active_asm();
            update_highlight_and_labels(&ui, &ctrl.autocomplete, &snap.text, is_asm);
            snap.cursor_offset
        } else {
            0
        }
    });

    // Toggle Comment Range (Ctrl + /) - Single line or Multi-line selection
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_toggle_comment_range(move |cursor_offset, anchor_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let (new_code, new_pos) =
            toggle_comment_in_code(&code, cursor_offset as usize, anchor_offset as usize);

        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);

        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.undo_manager.record_edit(&new_code, new_pos, true);
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        new_pos
    });

    // Legacy single offset fallback
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_toggle_comment(move |byte_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let (new_code, new_pos) =
            toggle_comment_in_code(&code, byte_offset as usize, byte_offset as usize);

        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);

        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.undo_manager.record_edit(&new_code, new_pos, true);
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        new_pos
    });

    // Duplicate Line (Ctrl + D)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_duplicate_line(move |byte_offset| {
        let Some(ui) = app_weak.upgrade() else {
            return 0;
        };
        let code = ui.get_code_text().to_string();
        let offset = (byte_offset as usize).min(code.len());
        let pre = &code[..offset];
        let line_start = pre.rfind('\n').map(|p| p + 1).unwrap_or(0);
        let line_end = code[offset..]
            .find('\n')
            .map(|p| offset + p)
            .unwrap_or(code.len());
        let current_line = &code[line_start..line_end];

        let col = offset - line_start;
        let duplicate_chunk = format!("\n{}", current_line);

        let mut new_code = String::with_capacity(code.len() + duplicate_chunk.len());
        new_code.push_str(&code[..line_end]);
        new_code.push_str(&duplicate_chunk);
        new_code.push_str(&code[line_end..]);

        let new_pos = (line_end + 1 + col) as i32;
        ui.set_code_text(SharedString::from(&new_code));
        ui.set_is_dirty(true);

        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.undo_manager.record_edit(&new_code, new_pos, true);
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &new_code, is_asm);

        new_pos
    });

    // Code Edited (Typing in Editor with Live Autocomplete Trigger)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_code_edited(move |new_code, cursor_offset| {
        let Some(ui) = app_weak.upgrade() else { return };
        ui.set_is_dirty(true);

        {
            let mut ctrl = ctrl_clone.lock().unwrap();
            ctrl.undo_manager.record_edit(new_code.as_str(), cursor_offset as i32, false);
        }

        let is_asm = ui.get_is_active_asm();
        {
            let ctrl = ctrl_clone.lock().unwrap();
            update_highlight_and_labels(&ui, &ctrl.autocomplete, new_code.as_str(), is_asm);
        }

        let lang = ui.get_current_language().to_string();
        let prefix = extract_prefix_at_offset(new_code.as_str(), cursor_offset as usize);
        if is_asm && !prefix.is_empty() {
            refresh_suggestions_ui(&ui, &ctrl_clone, prefix, &lang);
            let has_suggestions = ui.get_suggestion_list().row_count() > 0;
            if has_suggestions {
                ui.set_popup_anchor_x(ui.get_cursor_x());
                ui.set_popup_anchor_y(ui.get_cursor_y());
                let cy = ui.get_cursor_y();
                let line_h = ui.get_editor_line_height();
                let line_idx = if line_h > 0.0 {
                    (cy / line_h).round() as i32
                } else {
                    0
                };
                ui.set_popup_trigger_line(line_idx);
                ui.set_show_autocomplete_popup(true);
            } else {
                ui.set_show_autocomplete_popup(false);
            }
        } else {
            ui.set_show_autocomplete_popup(false);
        }
    });

    // Trigger Autocomplete (Ctrl + Space)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_trigger_autocomplete(move |cursor_offset| {
        let Some(ui) = app_weak.upgrade() else { return };
        let code = ui.get_code_text().to_string();
        let prefix = extract_prefix_at_offset(&code, cursor_offset as usize);
        let lang = ui.get_current_language().to_string();

        ui.set_popup_anchor_x(ui.get_cursor_x());
        ui.set_popup_anchor_y(ui.get_cursor_y());
        let cy = ui.get_cursor_y();
        let line_h = ui.get_editor_line_height();
        let line_idx = if line_h > 0.0 {
            (cy / line_h).round() as i32
        } else {
            0
        };
        ui.set_popup_trigger_line(line_idx);

        refresh_suggestions_ui(&ui, &ctrl_clone, prefix, &lang);
        ui.set_show_autocomplete_popup(true);
    });

    // Apply In-place Completion (from list click)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_apply_completion(move |snippet| {
        let Some(ui) = app_weak.upgrade() else { return };
        let code = ui.get_code_text().to_string();
        let cy = ui.get_cursor_y();
        let line_h = ui.get_editor_line_height();
        let line_idx = if line_h > 0.0 {
            (cy / line_h).round() as usize
        } else {
            0
        };
        let updated_code = apply_completion_to_code(&code, line_idx, snippet.as_str());
        ui.set_code_text(SharedString::from(&updated_code));
        ui.set_is_dirty(true);
        ui.set_show_autocomplete_popup(false);

        let ctrl = ctrl_clone.lock().unwrap();
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &updated_code, is_asm);
    });

    // Navigate Suggestions (Up/Down Arrow in Popup)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_navigate_suggestion(move |delta| {
        let Some(ui) = app_weak.upgrade() else { return };
        let ctrl = ctrl_clone.lock().unwrap();
        if ctrl.active_suggestions.is_empty() {
            return;
        }
        let current_name = ui.get_selected_sugg_name().to_string();
        let current_idx = ctrl
            .active_suggestions
            .iter()
            .position(|s| s.name == current_name)
            .unwrap_or(0);
        let len = ctrl.active_suggestions.len();
        let next_idx = if delta > 0 {
            (current_idx + 1) % len
        } else {
            (current_idx + len - 1) % len
        };
        if let Some(sugg) = ctrl.active_suggestions.get(next_idx) {
            ui.set_selected_sugg_name(SharedString::from(&sugg.name));
            ui.set_selected_sugg_category(SharedString::from(&sugg.category));
            ui.set_selected_sugg_syntax(SharedString::from(&sugg.syntax));
            ui.set_selected_sugg_summary(SharedString::from(&sugg.summary));
            ui.set_selected_sugg_flags(SharedString::from(&sugg.flags));
            ui.set_selected_sugg_cycles(SharedString::from(&sugg.cycles));
            ui.set_selected_sugg_insert_text(SharedString::from(&sugg.insert_text));
            ui.set_selected_sugg_icon_kind(SharedString::from(&sugg.icon_kind));
            ui.set_selected_sugg_example(SharedString::from(&sugg.example));
        }
    });

    // Toggle Language (RU / EN)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_toggle_language(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let cur = ui.get_current_language().to_string();
        let next_lang = if cur == "ru" { "en" } else { "ru" };
        ui.set_current_language(SharedString::from(next_lang));
        populate_docs_ui(&ui, next_lang);
        refresh_suggestions_ui(&ui, &ctrl_clone, ui.get_search_filter().as_str(), next_lang);
        if next_lang == "ru" {
            ui.set_status_message(SharedString::from("Язык изменён на Русский"));
        } else {
            ui.set_status_message(SharedString::from("Language set to English"));
        }
    });

    // Filter Changed in Autocomplete Drawer
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_filter_changed(move |query| {
        let Some(ui) = app_weak.upgrade() else { return };
        let lang = ui.get_current_language().to_string();
        refresh_suggestions_ui(&ui, &ctrl_clone, query.as_str(), &lang);
    });

    // Select Suggestion
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_select_suggestion(move |idx| {
        let Some(ui) = app_weak.upgrade() else { return };
        let ctrl = ctrl_clone.lock().unwrap();
        if let Some(sugg) = ctrl.active_suggestions.get(idx as usize) {
            ui.set_selected_sugg_name(SharedString::from(&sugg.name));
            ui.set_selected_sugg_category(SharedString::from(&sugg.category));
            ui.set_selected_sugg_syntax(SharedString::from(&sugg.syntax));
            ui.set_selected_sugg_summary(SharedString::from(&sugg.summary));
            ui.set_selected_sugg_flags(SharedString::from(&sugg.flags));
            ui.set_selected_sugg_cycles(SharedString::from(&sugg.cycles));
            ui.set_selected_sugg_insert_text(SharedString::from(&sugg.insert_text));
            ui.set_selected_sugg_icon_kind(SharedString::from(&sugg.icon_kind));
            ui.set_selected_sugg_example(SharedString::from(&sugg.example));
        }
    });

    // Insert Suggestion Template
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_insert_suggestion(move |snippet| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut current_code = ui.get_code_text().to_string();
        if !current_code.is_empty() && !current_code.ends_with('\n') {
            current_code.push('\n');
        }
        current_code.push_str("        ");
        current_code.push_str(snippet.as_str());
        current_code.push('\n');

        ui.set_code_text(SharedString::from(&current_code));
        ui.set_is_dirty(true);

        let ctrl = ctrl_clone.lock().unwrap();
        let is_asm = ui.get_is_active_asm();
        update_highlight_and_labels(&ui, &ctrl.autocomplete, &current_code, is_asm);
    });

    // Assemble Only (asmx20)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_run_assemble_only(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();

        // 1. Check if file is open
        let active_name = ui.get_active_file_name().to_string();
        if active_name.is_empty() {
            ctrl.append_log("[WARN] No active file is currently open to assemble.");
            sync_logs(&ui, &ctrl);
            return;
        }

        // Save file first
        let text = ui.get_code_text().to_string();
        let target_path = if let Some(path) = &ctrl.file_manager.active_file_path {
            path.clone()
        } else {
            ctrl.file_manager
                .current_dir
                .join(&active_name)
        };

        if let Err(e) = ctrl.file_manager.write_file_content(&target_path, &text) {
            ctrl.append_log(&format!("[ERROR] Save before assemble failed: {}", e));
            sync_logs(&ui, &ctrl);
            return;
        }
        ui.set_is_dirty(false);
        ui.set_status_message(SharedString::from("Building (.COM)..."));
        ui.set_status_color(Color::from_rgb_u8(137, 180, 250));

        // 2. Assemble with asmx20 on background thread (Never freezes UI)
        let app_weak_inner = app_weak.clone();
        let ctrl_clone_inner = Arc::clone(&ctrl_clone);
        std::thread::spawn(move || {
            let report = CompilerRunner::assemble_file(&target_path);
            let _ = slint::invoke_from_event_loop(move || {
                let Some(ui) = app_weak_inner.upgrade() else { return };
                let mut ctrl = ctrl_clone_inner.lock().unwrap();
                for log in &report.output_logs {
                    ctrl.append_log(log);
                }

                if report.success {
                    ui.set_status_message(SharedString::from("Build OK (.COM generated)"));
                    ui.set_status_color(Color::from_rgb_u8(166, 227, 161));
                } else {
                    ui.set_status_message(SharedString::from("Assembly Failed"));
                    ui.set_status_color(Color::from_rgb_u8(243, 139, 168));
                }

                sync_logs(&ui, &ctrl);
            });
        });
    });

    // Run in Emulator (asmx20 + cpmemu - Asynchronous, Never Freezes UI)
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_run_emulator(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();

        // 1. Check if file is open
        let active_name = ui.get_active_file_name().to_string();
        if active_name.is_empty() {
            ctrl.append_log("[WARN] No active file is currently open to assemble.");
            sync_logs(&ui, &ctrl);
            return;
        }

        // Save file first
        let text = ui.get_code_text().to_string();
        let target_path = if let Some(path) = &ctrl.file_manager.active_file_path {
            path.clone()
        } else {
            ctrl.file_manager
                .current_dir
                .join(&active_name)
        };

        if let Err(e) = ctrl.file_manager.write_file_content(&target_path, &text) {
            ctrl.append_log(&format!("[ERROR] Save before run failed: {}", e));
            sync_logs(&ui, &ctrl);
            return;
        }
        ui.set_is_dirty(false);
        ui.set_status_message(SharedString::from("Assembling & Launching (cpmemu)..."));
        ui.set_status_color(Color::from_rgb_u8(137, 180, 250));

        // 2. Assemble and Run on background thread (Never freezes UI)
        let app_weak_inner = app_weak.clone();
        let ctrl_clone_inner = Arc::clone(&ctrl_clone);
        std::thread::spawn(move || {
            let report = CompilerRunner::assemble_file(&target_path);
            let emu_logs = if report.success {
                if let Some(ref com) = report.com_path {
                    Some(CompilerRunner::run_in_emulator(com))
                } else {
                    None
                }
            } else {
                None
            };

            let _ = slint::invoke_from_event_loop(move || {
                let Some(ui) = app_weak_inner.upgrade() else { return };
                let mut ctrl = ctrl_clone_inner.lock().unwrap();
                for log in &report.output_logs {
                    ctrl.append_log(log);
                }

                if !report.success {
                    ui.set_status_message(SharedString::from("Build failed, run aborted"));
                    ui.set_status_color(Color::from_rgb_u8(243, 139, 168));
                } else if let Some(logs) = emu_logs {
                    for log in logs {
                        ctrl.append_log(&log);
                    }
                    ui.set_status_message(SharedString::from("Execution Complete (cpmemu)"));
                    ui.set_status_color(Color::from_rgb_u8(166, 227, 161));
                }

                sync_logs(&ui, &ctrl);
            });
        });
    });

    // Run Syntax Check
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_run_syntax_check(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        let code = ui.get_code_text().to_string();
        let report = CompilerRunner::validate_syntax(&code);

        for log in &report.output_logs {
            ctrl.append_log(log);
        }

        if report.success {
            ui.set_status_message(SharedString::from("Syntax Valid"));
            ui.set_status_color(Color::from_rgb_u8(166, 227, 161));
        } else {
            ui.set_status_message(SharedString::from("Syntax Errors Found"));
            ui.set_status_color(Color::from_rgb_u8(243, 139, 168));
        }

        sync_logs(&ui, &ctrl);
    });

    // Clear Output Console
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_clear_output(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.logs.clear();
        ctrl.logs.push("[CONSOLE] Output logs cleared.".to_string());
        sync_logs(&ui, &ctrl);
    });

    // Toggle Docs Mode
    let app_weak = app.as_weak();
    app.on_toggle_docs_mode(move || {
        let Some(ui) = app_weak.upgrade() else { return };
        let current = ui.get_editor_mode();
        if current == 2 {
            ui.set_editor_mode(0);
        } else {
            ui.set_editor_mode(2);
        }
    });

    // Label Clicked in Outline
    let ctrl_clone = Arc::clone(&controller_rc);
    let app_weak = app.as_weak();
    app.on_label_clicked(move |line_number| {
        let Some(ui) = app_weak.upgrade() else { return };
        let mut ctrl = ctrl_clone.lock().unwrap();
        ctrl.append_log(&format!("[OUTLINE] Jump target at line {}", line_number));
        ui.set_status_message(SharedString::from(format!("Label at line {}", line_number)));
        ui.set_status_color(Color::from_rgb_u8(249, 226, 175));
        sync_logs(&ui, &ctrl);
    });
}

fn refresh_files_ui(app: &AppWindow, controller_rc: &Arc<Mutex<IdeController>>) {
    let controller = controller_rc.lock().unwrap();
    app.set_current_dir_path(SharedString::from(
        controller
            .file_manager
            .current_dir
            .to_string_lossy()
            .to_string(),
    ));

    match controller.file_manager.list_directory() {
        Ok(entries) => {
            let items: Vec<FileItem> = entries
                .into_iter()
                .map(|e| FileItem {
                    name: SharedString::from(e.name),
                    path: SharedString::from(e.path.to_string_lossy().to_string()),
                    is_dir: e.is_dir,
                    is_asm: e.is_asm,
                    is_expanded: e.is_expanded,
                    depth: e.depth,
                    icon_name: SharedString::from(e.icon_name),
                    size_str: SharedString::from(e.size_formatted),
                })
                .collect();
            app.set_file_list(ModelRc::from(Rc::new(VecModel::from(items))));
        }
        Err(err) => {
            eprintln!("Failed to read directory: {}", err);
        }
    }
}

fn update_highlight_and_labels(
    app: &AppWindow,
    autocomplete: &AutocompleteEngine,
    code: &str,
    is_asm: bool,
) {
    let line_count = code.lines().count().max(1);
    let mut numbers_str = String::with_capacity(line_count * 5);
    for i in 1..=line_count {
        numbers_str.push_str(&i.to_string());
        numbers_str.push('\n');
    }
    app.set_line_numbers_text(SharedString::from(numbers_str));

    if !is_asm {
        app.set_highlight_lines(ModelRc::default());
        app.set_label_list(ModelRc::default());
        return;
    }

    let lines = highlight_document(code);
    let line_models: Vec<HighlightLineItem> = lines
        .into_iter()
        .map(|line| {
            let token_models: Vec<TokenItem> = line
                .tokens
                .into_iter()
                .map(|tok| TokenItem {
                    text: SharedString::from(tok.text),
                    color: tok.color,
                })
                .collect();
            HighlightLineItem {
                line_number: line.line_number,
                tokens: ModelRc::from(Rc::new(VecModel::from(token_models))),
            }
        })
        .collect();
    app.set_highlight_lines(ModelRc::from(Rc::new(VecModel::from(line_models))));

    let labels = autocomplete.get_user_labels(code);
    let label_items: Vec<LabelItem> = labels
        .into_iter()
        .map(|l| LabelItem {
            name: SharedString::from(l.name),
            line_number: l.line_number as i32,
        })
        .collect();
    app.set_label_list(ModelRc::from(Rc::new(VecModel::from(label_items))));
}

fn populate_docs_ui(app: &AppWindow, lang: &str) {
    let doc_items: Vec<DocItem> = crate::autocomplete::intel8080_docs::INTEL_8080_DOCS
        .iter()
        .map(|doc| DocItem {
            name: SharedString::from(doc.name),
            syntax: SharedString::from(doc.syntax),
            summary: SharedString::from(doc.get_summary(lang)),
            operands: SharedString::from(doc.operands),
            flags: SharedString::from(doc.flags),
            cycles: SharedString::from(doc.cycles),
            bytes: doc.bytes as i32,
            category: SharedString::from(doc.get_category(lang)),
        })
        .collect();
    app.set_docs_list(ModelRc::from(Rc::new(VecModel::from(doc_items))));
}


fn apply_completion_to_code(code: &str, line_idx: usize, insert_text: &str) -> String {
    let lines: Vec<&str> = code.lines().collect();
    if line_idx >= lines.len() {
        return format!("{}\n        {}\n", code, insert_text);
    }
    let current_line = lines[line_idx];
    let trimmed = current_line.trim_end();
    let word_start = trimmed
        .rfind(|c: char| !c.is_alphanumeric() && c != '_' && c != '.')
        .map(|pos| pos + 1)
        .unwrap_or(0);
    let prefix = &current_line[..word_start];
    let new_line = format!("{}{}", prefix, insert_text);

    let mut result = String::new();
    for (i, line) in code.lines().enumerate() {
        if i == line_idx {
            result.push_str(&new_line);
        } else {
            result.push_str(line);
        }
        result.push('\n');
    }
    if !code.ends_with('\n') && result.ends_with('\n') {
        result.pop();
    }
    result
}

fn refresh_suggestions_ui(
    app: &AppWindow,
    controller_rc: &Arc<Mutex<IdeController>>,
    query: &str,
    lang: &str,
) {
    let mut controller = controller_rc.lock().unwrap();
    let current_code = app.get_code_text().to_string();
    let suggestions = controller
        .autocomplete
        .get_suggestions_lang(query, &current_code, lang);
    controller.active_suggestions = suggestions.clone();

    if let Some(first) = suggestions.first() {
        app.set_selected_sugg_name(SharedString::from(&first.name));
        app.set_selected_sugg_category(SharedString::from(&first.category));
        app.set_selected_sugg_syntax(SharedString::from(&first.syntax));
        app.set_selected_sugg_summary(SharedString::from(&first.summary));
        app.set_selected_sugg_flags(SharedString::from(&first.flags));
        app.set_selected_sugg_cycles(SharedString::from(&first.cycles));
        app.set_selected_sugg_insert_text(SharedString::from(&first.insert_text));
        app.set_selected_sugg_icon_kind(SharedString::from(&first.icon_kind));
        app.set_selected_sugg_example(SharedString::from(&first.example));
    }

    let items: Vec<SuggestionItem> = suggestions
        .into_iter()
        .map(|s| SuggestionItem {
            name: SharedString::from(s.name),
            category: SharedString::from(s.category),
            syntax: SharedString::from(s.syntax),
            summary: SharedString::from(s.summary),
            flags: SharedString::from(s.flags),
            cycles: SharedString::from(s.cycles),
            insert_text: SharedString::from(s.insert_text),
            icon_kind: SharedString::from(s.icon_kind),
            example: SharedString::from(s.example),
        })
        .collect();
    app.set_suggestion_list(ModelRc::from(Rc::new(VecModel::from(items))));
}

fn parse_log_line(line: &str) -> (&str, Color, &str, Color) {
    let bytes = line.as_bytes();
    let (time_part, rest) = if bytes.starts_with(b"[") {
        if let Some(end_bracket) = line.find(']') {
            if end_bracket < 15 && bytes.get(end_bracket + 1) == Some(&b' ') {
                (&line[..=end_bracket + 1], &line[end_bracket + 2..])
            } else {
                ("", line)
            }
        } else {
            ("", line)
        }
    } else {
        ("", line)
    };

    if rest.starts_with("[SUCCESS]") {
        (
            if time_part.is_empty() { "[SUCCESS] " } else { time_part },
            Color::from_rgb_u8(166, 227, 161),
            rest.strip_prefix("[SUCCESS] ").unwrap_or(rest),
            Color::from_rgb_u8(166, 227, 161),
        )
    } else if rest.starts_with("[ERROR]") || rest.starts_with("[CPM ERR]") || rest.contains("error:") {
        (
            if time_part.is_empty() { "[ERROR] " } else { time_part },
            Color::from_rgb_u8(243, 139, 168),
            rest.strip_prefix("[ERROR] ").unwrap_or(rest),
            Color::from_rgb_u8(243, 139, 168),
        )
    } else if rest.starts_with("[WARN]") || rest.starts_with("[WARNING]") || rest.contains("warning:") {
        (
            if time_part.is_empty() { "[WARN] " } else { time_part },
            Color::from_rgb_u8(249, 226, 175),
            rest.strip_prefix("[WARN] ").unwrap_or(rest),
            Color::from_rgb_u8(249, 226, 175),
        )
    } else if rest.starts_with("[CMD]") {
        (
            if time_part.is_empty() { "[CMD] " } else { time_part },
            Color::from_rgb_u8(137, 220, 235),
            rest.strip_prefix("[CMD] ").unwrap_or(rest),
            Color::from_rgb_u8(205, 214, 244),
        )
    } else if rest.starts_with("[CPM OUTPUT]") {
        (
            "[CPM OUT] ",
            Color::from_rgb_u8(148, 226, 213),
            rest.strip_prefix("[CPM OUTPUT] ").unwrap_or(rest),
            Color::from_rgb_u8(255, 255, 255),
        )
    } else if rest.starts_with("[EMULATOR]") {
        (
            if time_part.is_empty() { "[EMULATOR] " } else { time_part },
            Color::from_rgb_u8(203, 166, 247),
            rest.strip_prefix("[EMULATOR] ").unwrap_or(rest),
            Color::from_rgb_u8(186, 194, 222),
        )
    } else if rest.starts_with("[SYSTEM]") || rest.starts_with("[TOOLCHAIN]") {
        (
            if time_part.is_empty() { "[SYSTEM] " } else { time_part },
            Color::from_rgb_u8(137, 180, 250),
            rest,
            Color::from_rgb_u8(205, 214, 244),
        )
    } else {
        (
            time_part,
            Color::from_rgb_u8(108, 112, 134),
            rest,
            Color::from_rgb_u8(205, 214, 244),
        )
    }
}

fn update_terminal_lines(app: &AppWindow, logs: &[String]) {
    let mut items = Vec::with_capacity(logs.len());
    for (idx, line) in logs.iter().enumerate() {
        let (prefix, prefix_color, text, text_color) = parse_log_line(line);
        items.push(TerminalLineItem {
            line_number: (idx + 1) as i32,
            prefix: SharedString::from(prefix),
            prefix_color,
            text: SharedString::from(text),
            text_color,
        });
    }
    app.set_terminal_lines(ModelRc::from(Rc::new(VecModel::from(items))));
}

fn extract_prefix_at_offset(code: &str, byte_offset: usize) -> &str {
    let bytes = code.as_bytes();
    let offset = byte_offset.min(bytes.len());
    let mut start = offset;
    while start > 0 {
        let b = bytes[start - 1];
        if b.is_ascii_alphanumeric() || b == b'_' || b == b'.' || b == b'?' || b == b'@' {
            start -= 1;
        } else {
            break;
        }
    }
    let mut end = offset;
    while end < bytes.len() {
        let b = bytes[end];
        if b.is_ascii_alphanumeric() || b == b'_' || b == b'.' || b == b'?' || b == b'@' {
            end += 1;
        } else {
            break;
        }
    }
    &code[start..end]
}

fn toggle_comment_in_code(code: &str, cursor_offset: usize, anchor_offset: usize) -> (String, i32) {
    let bytes = code.as_bytes();
    let min_off = cursor_offset.min(anchor_offset).min(bytes.len());
    let max_off = cursor_offset.max(anchor_offset).min(bytes.len());

    let first_line_start = bytes[..min_off]
        .iter()
        .rposition(|&b| b == b'\n')
        .map(|p| p + 1)
        .unwrap_or(0);

    let last_line_end = if max_off > min_off && bytes.get(max_off.saturating_sub(1)) == Some(&b'\n') {
        max_off.saturating_sub(1)
    } else {
        bytes[max_off..]
            .iter()
            .position(|&b| b == b'\n')
            .map(|p| max_off + p)
            .unwrap_or(bytes.len())
    };

    let target_section = &code[first_line_start..last_line_end];
    let lines: Vec<&str> = target_section.split('\n').collect();

    let mut all_commented = true;
    let mut has_non_empty = false;
    for line in &lines {
        let trimmed = line.trim_start();
        if !trimmed.is_empty() {
            has_non_empty = true;
            if !trimmed.starts_with(';') {
                all_commented = false;
                break;
            }
        }
    }
    if !has_non_empty {
        all_commented = false;
    }

    let mut result_section = String::with_capacity(target_section.len() + lines.len() * 2);
    for (idx, line) in lines.iter().enumerate() {
        if idx > 0 {
            result_section.push('\n');
        }
        let trimmed = line.trim_start();
        let ws_len = line.len() - trimmed.len();
        let ws = &line[..ws_len];

        if all_commented {
            if let Some(uncommented) = trimmed.strip_prefix("; ") {
                result_section.push_str(ws);
                result_section.push_str(uncommented);
            } else if let Some(uncommented) = trimmed.strip_prefix(';') {
                result_section.push_str(ws);
                result_section.push_str(uncommented);
            } else {
                result_section.push_str(line);
            }
        } else if trimmed.is_empty() {
            result_section.push_str(line);
        } else {
            result_section.push_str(ws);
            result_section.push_str("; ");
            result_section.push_str(trimmed);
        }
    }

    let mut new_code = String::with_capacity(code.len() + lines.len() * 2);
    new_code.push_str(&code[..first_line_start]);
    new_code.push_str(&result_section);
    let new_cursor_pos = new_code.len();
    new_code.push_str(&code[last_line_end..]);

    (new_code, new_cursor_pos as i32)
}
